import numpy as np

def heuristic(dist_m, turn_deg, swath_len_m, energy_left_frac, depot_dist_m, fits):
    """Return a positive desirability score for each candidate swath (numpy arrays, same length).
    dist_m: distance to candidate start (m); turn_deg: turning needed (deg); swath_len_m: candidate length (m);
    energy_left_frac: battery fraction left (scalar 0..1); depot_dist_m: distance from candidate end to depot (m);
    fits: 1.0 if the candidate fits in the remaining battery, else 0.0."""
    return 1.0 / (dist_m + 1.0)

import numpy as np

def heuristic(dist_m, turn_deg, swath_len_m, energy_left_frac, depot_dist_m, fits):
    def clean(x, nan=0.0, pos=1e12, neg=0.0):
        x = np.asarray(x, dtype=float)
        return np.maximum(np.nan_to_num(x, nan=nan, posinf=pos, neginf=neg), 0.0)

    dist = clean(dist_m)
    turn = np.clip(np.nan_to_num(
        np.asarray(turn_deg, dtype=float), nan=180.0, posinf=360.0, neginf=0.0
    ), 0.0, 360.0)
    length = clean(swath_len_m)
    depot = clean(depot_dist_m)
    fit = np.clip(np.nan_to_num(
        np.asarray(fits, dtype=float), nan=0.0, posinf=1.0, neginf=0.0
    ), 0.0, 1.0)
    charge = float(np.clip(np.nan_to_num(
        energy_left_frac, nan=0.0, posinf=1.0, neginf=0.0
    ), 0.0, 1.0))

    log_cost = (
        np.log1p(dist)
        + np.log1p(0.30 * (turn / 180.0) ** 2)
        + np.log1p(0.10 * length / (length + 100.0))
        + np.log1p((0.05 + 0.40 * (1.0 - charge) ** 2)
                   * depot / (depot + length + 100.0))
    )
    log_score = -log_cost + np.log(0.01 + 0.99 * fit)
    return np.maximum(np.exp(np.clip(log_score, -700.0, 700.0)), 1e-300)
